        }

        internal ReportAnalyte Add(TestAnalyte analyte, string orderingAnalyteCode, string accessionFacility, string performFacility, long spmOrderTestId = 0, SPMStatusValue spmStatus = SPMStatusValue.None)
        {

            var oa = new ReportAnalyte(m_parent, analyte, orderingAnalyteCode, spmStatus: spmStatus);
            oa.SetPerformingFacility(performFacility);
            oa.SetAccessioningFacility(accessionFacility);
            oa.SetSPMOrderTestId(spmOrderTestId);
            Log.Debug($"Adding analyte code={oa.Code} spmStatus={oa.SPMStatus}");

            if (ReferenceEquals(m_parent.GetType(), typeof(Report)) && analyte.IsCalculation)
                ((Report)m_parent).m_hasCalcAnalytes = true;
            List.Add(oa);

            if (ReferenceEquals(m_parent.GetType(), typeof(Report)))
            {
                ((Report)m_parent).AddToTestCodeHash(orderingAnalyteCode);
                Log.Debug("Calling EvaluateRulesEx with RuleSetRelease (68)");
                ((Report)m_parent).EvaluateRulesEx(oa, "", Configuration.RuleSetRelease);
            }

            return oa;

        }

