        public ReportAnalyte Find(long orderAnalyteId, bool searchDeleted)
        {
            foreach (ReportAnalyte a in List)
            {
                if (a.ID == orderAnalyteId)
                    return a;
            }

            if (searchDeleted)
            {
                foreach (ReportAnalyte a in List.ArchivedDeletedList)
                {
                    if (a.ID == orderAnalyteId)
                        return a;
                }
            }
            return null;
        }

        public ReportAnalyte FindFirst(string analyteCode, int referenceLabId = 0, transmitStatusType transmitStatus = transmitStatusType.NotSet)
        {
            if (referenceLabId != 0)
            {
                foreach (ReportAnalyte a in List)
                {
                    if (transmitStatus == transmitStatusType.NotSet || a.TransmitStatus == transmitStatus)
                    {
                        // AG 12/8/2008 - Check for Ordering testCode.
                        // If a.Analyte.ReferenceLabeAnalyteCode = analyteCode AndAlso a.Analyte.ReferenceLabId = referenceLabId Then Return a
                        if (a.Analyte.ReferenceLabId == referenceLabId)
                        {
                            if (string.Equals(NormalizeAnalyteCode(a.Analyte.ReferenceLabeAnalyteCode), NormalizeAnalyteCode(analyteCode), StringComparison.OrdinalIgnoreCase))
                            {
                                return a;
                            }

                            // AG 5/27/09 - Added this because the channel pads testcodes less than 4 char long with zeroes.
                            if (string.Equals(NormalizeAnalyteCode(a.Analyte.ReferenceLabeAnalyteCode.PadLeft(4, '0')), NormalizeAnalyteCode(analyteCode.PadLeft(4, '0')), StringComparison.OrdinalIgnoreCase))
                            {
                                return a;
                            }

                            // Search by the reflab ordering code
                            if (ReferenceEquals(a.Analyte.GetType(), typeof(RefAnalyte)))
                            {
                                if (string.Equals(NormalizeAnalyteCode(((RefAnalyte)a.Analyte).ReferenceLabOrderingAnalyteCode.PadLeft(4, '0')), NormalizeAnalyteCode(analyteCode.PadLeft(4, '0')), StringComparison.OrdinalIgnoreCase))
                                {
                                    return a;
                                }
                            }
                        }
                    }
                }
            }
            else
            {
                foreach (ReportAnalyte a in List)
                {
                    if (transmitStatus == transmitStatusType.NotSet || a.TransmitStatus == transmitStatus)
                    {
                        if (string.Equals(NormalizeAnalyteCode(a.Analyte.Code), NormalizeAnalyteCode(analyteCode), StringComparison.OrdinalIgnoreCase))
                        {
                            return a;
                        }

                        // AG 12/8/2008 - Check for Ordering testCode.
                        // If a.OrderingAnalyteCode.TrimStart(New Char() {"0"}) = analyteCode.TrimStart(New Char() {"0"}) Then Return a
                    }
                }

                // Now search aliases aka testcodemapping
                foreach (ReportAnalyte a in List)
                {
                    if (transmitStatus == transmitStatusType.NotSet || a.TransmitStatus == transmitStatus)
                    {
                        foreach (TestCodeMapping m in a.Analyte.TestCodeAliasList)
                        {
                            if (string.Equals(NormalizeAnalyteCode(m.AlternateTestCode), NormalizeAnalyteCode(analyteCode), StringComparison.OrdinalIgnoreCase))
                            {
                                return a;
                            }
                        }
                    }
                }
            }

            return null;
        }

        private string NormalizeAnalyteCode(string code)
        {
            if (string.IsNullOrWhiteSpace(code))
                return string.Empty;

            code = code.Trim().TrimStart('0');

            return string.IsNullOrEmpty(code)
                ? "0"
                : code.ToUpperInvariant();
        }

        public ReportAnalyte[] Find(string analyteCode, string orderedCode)
        {

            var analytes = new List<ReportAnalyte>();

            foreach (ReportAnalyte a in List)
            {
                if ((a.Analyte.Code.TrimStart(new char[] { '0' }).ToUpper() ?? "") == (analyteCode.TrimStart(new char[] { '0' }).ToUpper() ?? "") && a.ContainsOrderCode(orderedCode))   // 'a.OrderingAnalyteCode.TrimStart(New Char() {"0"}) = orderedCode.TrimStart(New Char() {"0"}) Then
                {
                    analytes.Add(a);
                }
                // For those that are aliases
                foreach (TestCodeMapping m in a.Analyte.TestCodeAliasList)
                {
                    if ((m.AlternateTestCode.TrimStart(new char[] { '0' }).ToUpper() ?? "") == (analyteCode.TrimStart(new char[] { '0' }).ToUpper() ?? "") && a.ContainsOrderCode(orderedCode))   // 'a.OrderingAnalyteCode.TrimStart(New Char() {"0"}) = orderedCode.TrimStart(New Char() {"0"}) Then
                    {
                        analytes.Add(a);
                    }
                }
            }

            return analytes.ToArray();

        }

        public ReportAnalyte[] Find(string analyteCode, int referenceLabId = 0)
        {

            var analytes = new List<ReportAnalyte>();

            if (referenceLabId != 0)
            {
                foreach (ReportAnalyte a in List)
                {
                    if ((a.Analyte.ReferenceLabeAnalyteCode.ToUpper() ?? "") == (analyteCode.ToUpper() ?? "") && a.Analyte.ReferenceLabId == referenceLabId)
                    {
                        analytes.Add(a);
                    }
                }
            }
            else
            {
                foreach (ReportAnalyte a in List)
                {
                    if ((a.Analyte.Code.TrimStart(new char[] { '0' }).ToUpper() ?? "") == (analyteCode.TrimStart(new char[] { '0' }).ToUpper() ?? ""))
                    {
                        analytes.Add(a);
                    }
                    // For those that are aliases
                    foreach (TestCodeMapping m in a.Analyte.TestCodeAliasList)
                    {
                        if ((m.AlternateTestCode.TrimStart(new char[] { '0' }).ToUpper() ?? "") == (analyteCode.TrimStart(new char[] { '0' }).ToUpper() ?? ""))
                        {
                            analytes.Add(a);
                        }
                    }
                }
            }
            return analytes.ToArray();
        }

        internal void Update()
        {
            m_list.Update();
            if (Configuration.LISSettings.GetBool("ReportAnalyteBatching"))
            {
                var archiveList = new ReportAnalyteList();
                foreach (ReportAnalyte a in m_list.ArchivedDeletedList)
                {
                    if (a.IsDirty)
                        archiveList.Add(a);
                }
                if (archiveList.Count > 0)
                {
                    archiveList.Update();
                }
            }

            else
            {
                foreach (ReportAnalyte a in m_list.ArchivedDeletedList)
                {
                    if (a.IsDirty)
                        a.Update();
                }
            }

        }

        internal void SetOrigResultStatus()
        {
            m_list.SetOrigResultStatus();
        }

        public override bool IsDirty
        {
            get
            {
                if (m_list.IsDirty)
                    return true;

                // Archived analytes can be updated!
                foreach (ReportAnalyte a in m_list.ArchivedDeletedList)
                {
                    if (a.IsDirty)
                        return true;
                }
                return false;
            }
        }

        public List<string> GetAuditItems()
        {
            var lst = new List<string>();

            foreach (ReportAnalyte c in m_list)
                lst.AddRange(c.GetFormattedAuditItems);

            foreach (ReportAnalyte c in m_list.ArchivedDeletedList)
                lst.AddRange(c.GetFormattedAuditItems);

            return lst;

        }

        public void ResetAudit()
        {
            foreach (ReportAnalyte c in m_list)
                c.ResetAuditItems();
        }


